}

// ─── Typed errors ────────────────────────────────────────────────────────────────

/** Thrown by assertRamOk()/downloadModel() when this machine doesn't meet a model's minTotalRamGB. */
export class InsufficientRamError extends Error {
  constructor(
    public readonly modelId: string,
    public readonly requiredGB: number,
    public readonly availableGB: number,
    public readonly suggestion?: LocalModelEntry
  ) {
    const suggestText = suggestion
      ? ` Try "${suggestion.label}" instead (needs ${suggestion.minTotalRamGB} GB).`
      : ''
    super(
      `This model needs at least ${requiredGB} GB of RAM — this machine has ${availableGB.toFixed(1)} GB.${suggestText}`
    )
    this.name = 'InsufficientRamError'
  }
}

/** Thrown when a downloaded file's streamed sha256 doesn't match its manifest pin. The bad file is
 *  deleted before this throws — callers never see a corrupt file left on disk. */
export class ChecksumMismatchError extends Error {
  constructor(
    public readonly modelId: string,
    public readonly file: 'gguf' | 'mmproj',
    public readonly expectedSha256: string,
    public readonly actualSha256: string
  ) {
    super(
      `Download corrupted for ${modelId} (${file}): checksum mismatch (expected ${expectedSha256.slice(0, 8)}…, ` +
        `got ${actualSha256.slice(0, 8)}…). Please retry the download.`
    )
    this.name = 'ChecksumMismatchError'
  }
}

/** Thrown when a download stream ends with fewer (or more) bytes than the manifest pin expects — a
 *  truncated connection would otherwise pass the byte-size check silently if only length were compared
 *  post-hoc; this fires from inside the same streaming pass that also tracks the hash. */
export class IncompleteDownloadError extends Error {
  constructor(
    public readonly modelId: string,
    public readonly file: 'gguf' | 'mmproj',
    public readonly expectedBytes: number,
    public readonly receivedBytes: number
  ) {
    super(
      `Incomplete download for ${modelId} (${file}): got ${receivedBytes} of ${expectedBytes} bytes. Please retry.`
    )
    this.name = 'IncompleteDownloadError'
  }
}

// ─── Audit ───────────────────────────────────────────────────────────────────────
// logger.ts's AuditEvent union now names all three of this module's events directly (Rock 3) — no cast
// needed.
type LocalModelAuditEvent = Extract<AuditEvent, `local.model.${string}`>
function localAudit(event: LocalModelAuditEvent, detail: Record<string, unknown>): void {
  auditLog(event, detail)
}

// ─── RAM gate ────────────────────────────────────────────────────────────────────

function totalRamGB(): number {
  return totalmem() / 1024 ** 3
}

/** The smallest-footprint OTHER model in the manifest — named in the RAM-gate error so a refusal always
 *  offers a concrete next step instead of a dead end. Ties on minTotalRamGB break on total download size. */
function smallerModelSuggestion(excludeId: string): LocalModelEntry | undefined {
  const others = LOCAL_MODELS.filter((m) => m.id !== excludeId)
  if (others.length === 0) return undefined
  return [...others].sort(
    (a, b) =>
      a.minTotalRamGB - b.minTotalRamGB || a.gguf.bytes + a.mmproj.bytes - (b.gguf.bytes + b.mmproj.bytes)
  )[0]
}

/** Refuses download/load when this machine's total RAM is below the model's minTotalRamGB. Exported so
 *  the future load path (local-runtime.ts) can reuse the exact same gate rather than re-deriving it. */
export function assertRamOk(id: string): void {
  const entry = getModel(id)
  const available = totalRamGB()
  if (available < entry.minTotalRamGB) {
    throw new InsufficientRamError(id, entry.minTotalRamGB, available, smallerModelSuggestion(id))
  }
}

// ─── Storage paths (main-process only — never sent to the renderer) ──────────────

function modelDir(id: string): string {
  return join(app.getPath('userData'), 'local-llm', 'models', id)
}

function filePath(id: string, file: 'gguf' | 'mmproj'): string {
  return join(modelDir(id), file === 'gguf' ? 'model.gguf' : 'mmproj.gguf')
}

export interface LocalModelPaths {
  dir: string
  gguf: string
  mmproj: string
}

/** Absolute on-disk paths for a model's files. Main-process internal use only (e.g. spawning the
 *  sidecar) — never expose the return value over IPC. */
export function modelPaths(id: string): LocalModelPaths {
  getModel(id) // throws on an unknown id
  return { dir: modelDir(id), gguf: filePath(id, 'gguf'), mmproj: filePath(id, 'mmproj') }
}

function fileMatches(path: string, expectedBytes: number): boolean {
  try {
    return statSync(path).size === expectedBytes
  } catch {
    return false
  }
}

/** True only when both the gguf and mmproj files exist and their size matches the manifest pin. */
export function isDownloaded(id: string): boolean {
  const entry = getModel(id)
  const paths = modelPaths(id)
  return fileMatches(paths.gguf, entry.gguf.bytes) && fileMatches(paths.mmproj, entry.mmproj.bytes)
}

function safeUnlink(path: string): void {
  try {
    unlinkSync(path)
  } catch {
    /* already gone */
  }
}

export function deleteModel(id: string): void {
  getModel(id) // throws on an unknown id
  rmSync(modelDir(id), { recursive: true, force: true })
  localAudit('local.model.delete', { modelId: id })
}

/** Renderer-safe metadata only — never a path, port, or key. Matches the manifest law's public surface:
 *  id, label, sizes, downloaded state, RAM requirement. */
export interface LocalModelSummary {
  id: string
  label: string
  minTotalRamGB: number
  ggufBytes: number
  mmprojBytes: number
  totalBytes: number
  downloaded: boolean
}

export function listModels(): LocalModelSummary[] {
  return LOCAL_MODELS.map((m) => ({
    id: m.id,
    label: m.label,
    minTotalRamGB: m.minTotalRamGB,
    ggufBytes: m.gguf.bytes,
    mmprojBytes: m.mmproj.bytes,
    totalBytes: m.gguf.bytes + m.mmproj.bytes,
    downloaded: isDownloaded(m.id)
  }))
}

// ─── Download ────────────────────────────────────────────────────────────────────

export interface DownloadProgress {
  modelId: string
  file: 'gguf' | 'mmproj'
  received: number
  total: number
}
export type ProgressCallback = (p: DownloadProgress) => void

/** One in-flight AbortController per model id, so cancelDownload(id) can reach the right transfer. */
const activeDownloads = new Map<string, AbortController>()

/** GET url, dispatching to node:http or node:https by scheme. Every manifest URL is a hardcoded
 *  huggingface.co https URL — the http branch only ever activates in tests against a local mock server,
 *  never in production, since we never fetch an arbitrary (non-manifest) URL. */
function rawGet(
  url: string,
  headers: Record<string, string>,
  cb: (res: IncomingMessage) => void

  let loginItemOpenAtLogin = false
  try {
    loginItemOpenAtLogin = app.getLoginItemSettings().openAtLogin
  } catch {
    /* not supported on this platform */
  }
  // Active provider is usable: key present AND any provider-specific setup done (Dust needs a workspace +
  // a chosen base agent; custom needs an https base URL). Drives the add-key CTA so it only shows when the
  // app genuinely can't answer yet — not when a key for a DIFFERENT provider exists.
  const activeDef = PROVIDERS[s.provider]
  // Org allowlist (null = unrestricted) — the SAME source of truth askStart's attempt()/failover() enforce
  // at request time. Folding it in here keeps UI readiness from drifting out of sync with what's actually
  // allowed to answer (previously a blocked provider could show "ready" with no setup CTA, then reject
  // every ask).
  const allowed = getAllowedProviders()
  const providerReady =
    (!allowed || allowed.includes(s.provider)) &&
    (activeDef.kind === 'cli'
      ? !!s.cliConnected[s.provider]
      : hasApiKey(s.provider) &&
        (s.provider === 'dust'
          ? !!s.dustWorkspaceId.trim() && !!s.providerModels.dust
          : s.provider === 'custom'
            ? /^https:\/\//i.test(s.customBaseUrl) && !!s.providerModels.custom
            : true))
  // Métis Local readiness (PLAN.md §4.3) — task-independent base, then one per in-scope task. Derived by
  // local-routing.ts's localBaseReady() so this snapshot and the live routing decision (attempt()/
  // pickFailover below) can never drift apart.
  const localReady = localBaseReady(s, allowed)
  const localSuggestReady = localReady && s.localLlm.useFor.suggest
  const localSummaryReady = localReady && s.localLlm.useFor.summary
  const localVisionReady = localReady && s.localLlm.useFor.vision
  return {
    ...s,
    hasApiKey: hasApiKey(s.provider),
    providerReady,
    // gates screen-ask so shots never hit a non-vision model — ORs localVisionReady so a local-only setup
    // (no cloud provider configured at all) still counts as vision-ready.
    visionReady: (providerReady && activeDef.vision) || localVisionReady,
    // "Some configured provider can read images" — not necessarily the ACTIVE one. Mirrors the failover
    // candidate test (~1287): a keyed/CLI-connected provider with vision. Lets the renderer route a
    // screen-ask/quick-action to capture even when the active provider (e.g. Dust) is text-only, because
    // the main process transparently fails the vision turn over to this provider instead of dead-ending.
    // ORs localVisionReady for the same local-only-setup reason as visionReady above.
    visionAvailable:
      (Object.keys(PROVIDERS) as ProviderId[]).some(
        (p) =>
          PROVIDERS[p].vision &&
          (!allowed || allowed.includes(p)) &&
          (PROVIDERS[p].kind === 'cli' ? !!s.cliConnected[p] : hasApiKey(p))
      ) || localVisionReady,
    localReady,
    localSuggestReady,
    localSummaryReady,
    localVisionReady,
    // Live sidecar process state (distinct from localReady's eligibility check) — drives the Local AI
    // card's status line only.
    localRuntimeRunning: localRuntime.isRunning(),
    hasKeys: hasKeysMap(),
    hasEncryption: encryptionAvailable(),
    resolvedMeetingsFolder: resolveMeetingsFolder(s),
    managedKeys: getLockedKeys(),
    envKeys: getEnvKeyProviders(),
    loginItemOpenAtLogin
  }
}

import { modelPaths as resolveLocalModelPaths, verifyIntegrity } from './local-models'
import * as localRuntime from './local-runtime'
import { streamOpenAI } from './openai'
import { type StreamOptions, type StreamHandle, errMsg } from './shared'

/**
 * Métis Local provider strategy (PLAN.md §4.2/§4.3) — a thin shim over streamOpenAI: the llama-server
 * sidecar speaks the same OpenAI-compatible /v1/chat/completions surface openai.ts already talks to, so
 * this module's only job is (1) making sure the sidecar is running against the configured model, (2)
 * injecting the per-session sidecar key instead of a stored API key, and (3) pinning the llama-server slot
 * for the request's mode so per-slot prompt caching (cache_prompt) actually reuses the transcript prefix.
 * `opts.model` is the configured local-models.ts manifest id — index.ts resolves it from
 * settings.localLlm.modelId (not the generic per-provider model picker), see local-routing.ts.
 *
 * Async start must not block returning a handle: attempt() in index.ts stores the returned StreamHandle
 * synchronously before any await here runs, so a synchronous throw would never be catchable by it — errors
 * are reported via handlers.onError instead, exactly like openai.ts's own async-body pattern (its `custom`
 * baseURL guard fires onError via queueMicrotask for the same reason).
 */

/**
 * Ensure the sidecar is running against `modelId`. Extracted out of streamLocal so index.ts's local:prewarm
 * handler (PLAN.md §4.4's pre-warm path, Rock 5) can reach the EXACT same start logic without duplicating
 * it — both callers must resolve the same manifest paths and go through the same local-runtime.ts start()
 * call. Always delegates the running/starting/switch decision to start() itself (F2 hardening: start() is
 * idempotent per-model — a no-op when this exact model is already running, an in-flight-await when a start
 * is already underway, and a stop-then-restart when a DIFFERENT model is requested — so early-returning on
 * isRunning() here was both redundant and the thing that let a model switch never actually happen).
 * Re-verifies the model files' sha256 against the manifest (F5 hardening) before starting whenever the
 * requested GGUF isn't the one already active: either a COLD start (state 'stopped') or a model SWITCH
 * requested while the runtime is already running/starting (G2 hardening — getState() alone can't see a
 * switch, since it stays 'running'/'starting' throughout; getActiveModelKey() is what catches the new,
 * not-yet-verified GGUF). A warm request for the SAME model that's already active/starting skips the
 * re-hash — never on every live-meeting request against an unchanged model. A mismatch throws and start()
 * is never reached, so a corrupt file never reaches llama-server.
 */
export async function ensureLocalRuntimeStarted(modelId: string): Promise<void> {
  const paths = resolveLocalModelPaths(modelId)
  if (localRuntime.getState() === 'stopped' || localRuntime.getActiveModelKey() !== paths.gguf) {
    await verifyIntegrity(modelId)
  }
  await localRuntime.start({ gguf: paths.gguf, mmproj: paths.mmproj })
}

export function streamLocal(opts: StreamOptions): StreamHandle {
  let aborted = false
  let inner: StreamHandle | null = null

  void (async () => {
    try {
      await ensureLocalRuntimeStarted(opts.model)
      if (aborted) return // caller aborted while the sidecar was still starting — never start a stream
      localRuntime.markActivity()
      // Suggest and summary pin the SAME slots the pre-warm path (Rock 5) targets, so cache_prompt
      // actually hits on the real request. Vision (and any other in-scope mode) still asks for
      // cache_prompt without pinning a slot — a screenshot turn has no reusable transcript prefix.
      const llamaSlotOptions =
        opts.req.mode === 'suggest'
          ? { id_slot: 0, cache_prompt: true }
          : opts.req.mode === 'summary'
            ? { id_slot: 1, cache_prompt: true }
            : { cache_prompt: true }
      inner = streamOpenAI({
        ...opts,
        baseURL: localRuntime.baseURL(),
        apiKey: localRuntime.sessionKey(),
        llamaSlotOptions
      })
    } catch (err) {
      if (!aborted) opts.handlers.onError(errMsg(err))
    }
  })()

  return {
    abort: () => {
      aborted = true
      inner?.abort()
      // Accepted behavior (audit risk, by design): if the sidecar is still starting when this fires, the
      // in-flight ensureLocalRuntimeStarted()/start() call is NOT cancelled — it runs to completion and the
      // sidecar stays up, reclaimed later by the normal 15-minute idle-stop rather than torn down here.
      // Cancelling a mid-spawn llama-server process isn't worth the complexity for what's already a rare,
      // best-effort UX cancel (Cancel button / a new ask superseding this one).
    }
  }
}
